def metrics(matrix):
    n = len(matrix)
    total = sum(sum(row) for row in matrix)
    diag = sum(matrix[i][i] for i in range(n))
    accuracy = round(diag / total, 4) if total else 0.0
    per_class = {}
    for i in range(n):
        row_sum = sum(matrix[i])
        col_sum = sum(matrix[r][i] for r in range(n))
        precision = round(matrix[i][i] / col_sum, 4) if col_sum else 0.0
        recall = round(matrix[i][i] / row_sum, 4) if row_sum else 0.0
        if precision + recall:
            f1 = round(2 * precision * recall / (precision + recall), 4)
        else:
            f1 = 0.0
        per_class[i] = {'precision': precision, 'recall': recall, 'f1': f1}
    return {'accuracy': accuracy, 'per_class': per_class}

print(metrics([[45, 2, 3], [1, 47, 2], [6, 2, 42]]))

